(x, y, t) => {
  const cx = 240, cy = 120;
  const w1x = Math.sin(x*0.015+t*0.2)*20 + Math.cos(y*0.012-t*0.15)*15;
  const w1y = Math.cos(y*0.015-t*0.22)*20 + Math.sin(x*0.013+t*0.18)*15;
  const w2x = Math.sin(x*0.035+t*0.4)*8 + Math.cos(y*0.028-t*0.35)*6;
  const w2y = Math.cos(y*0.032-t*0.38)*8 + Math.sin(x*0.03+t*0.42)*6;
  const sx = x + w1x + w2x, sy = y + w1y + w2y;
  const src = [
    [160+Math.sin(t*0.5)*100,80+Math.cos(t*0.35)*50,0.07,2.0,1.0],
    [320+Math.cos(t*0.45)*100,160+Math.sin(t*0.6)*50,0.09,1.7,0.9],
    [240+Math.sin(t*0.25+2)*140,120+Math.cos(t*0.4+1)*90,0.055,2.3,1.1],
    [120+Math.cos(t*0.7+1)*80,180+Math.sin(t*0.5+3)*60,0.11,1.5,0.85],
    [360+Math.sin(t*0.35+4)*90,60+Math.cos(t*0.8+2)*70,0.065,2.6,1.05],
    [240+Math.cos(t*0.3+5)*120,200+Math.sin(t*0.45)*80,0.08,1.9,0.95],
    [80+Math.sin(t*0.55+3)*70,40+Math.cos(t*0.65+4)*50,0.1,2.1,0.8],
    [400+Math.cos(t*0.4+2)*60,220+Math.sin(t*0.75)*40,0.075,1.8,1.15]
  ];
  let aS=0,iS=0,tw=0;
  for(const[sX,sY,f,sp,w]of src){
    const d=Math.sqrt((sx-sX)**2+(sy-sY)**2);
    const dc=1.0/(1.0+d*0.003);
    aS+=Math.sin(d*f-t*sp)*dc*w;
    iS+=Math.sin(d*f*0.7+t*sp*0.6+1.5)*dc*w;
    tw+=w;
  }
  const act=aS/tw,inh=iS/tw;
  const bg1=(Math.sin(sx*0.03+sy*0.02+t*0.7)+Math.sin(sx*0.025-sy*0.035+t*1.0))/2;
  const bg2=Math.sin((sx+sy)*0.1+t*2.2)*0.3+Math.sin((sx-sy)*0.08-t*1.8)*0.3;
  const bg3=Math.sin(sx*0.08+sy*0.06-t*1.5)*Math.cos(sx*0.05-sy*0.07+t*1.2)*0.2;
  const bg=bg1+bg2+bg3;
  const dist=Math.sqrt((sx-cx)**2+(sy-cy)**2),ang=Math.atan2(sy-cy,sx-cx);
  const sp1=Math.sin(dist*0.04-ang*3-t*1.3)+Math.sin(dist*0.035+ang*4-t*1.0);
  const sp2=Math.sin(dist*0.06-ang*2+t*0.8)*0.5;
  const spiral=(sp1+sp2)*0.35;
  const laplacian=bg*0.3+spiral*0.2;
  const rd=Math.tanh((act-inh*0.65+bg*0.25+spiral+laplacian)*2.5);
  const cell=Math.tanh((Math.sin(sx*0.13)*Math.sin(sy*0.13)+Math.sin((sx+sy)*0.09+t)*0.4+Math.sin(sx*0.07-t*0.5)*Math.sin(sy*0.08+t*0.3)*0.3)*1.3)*0.25;
  const micro=Math.sin(sx*0.25+t*3)*Math.sin(sy*0.25-t*2.5)*0.08;
  const blend=rd*0.65+cell*0.2+micro,v=blend*0.5+0.5;
  const pal=[
    [5,12,45],[10,35,78],[18,72,112],[22,118,135],
    [48,168,148],[115,188,135],[195,192,95],[228,172,65],
    [215,125,58],[175,75,55],[135,42,55],[85,22,48],[42,14,45],[5,12,45]
  ];
  const idx=v*(pal.length-1),i=Math.min(idx|0,pal.length-2),f=idx-i;
  const sf=f*f*(3-2*f);
  const lum=0.85+Math.sin(rd*Math.PI)*0.15;
  const edge=Math.abs(rd)>0.65?1.0+(Math.abs(rd)-0.65)*0.8:1.0;
  const vig=1.0-Math.pow(dist/300,2)*0.15;
  const fl=lum*edge*vig;
  return[
    Math.min(255,(pal[i][0]+(pal[i+1][0]-pal[i][0])*sf)*fl)|0,
    Math.min(255,(pal[i][1]+(pal[i+1][1]-pal[i][1])*sf)*fl)|0,
    Math.min(255,(pal[i][2]+(pal[i+1][2]-pal[i][2])*sf)*fl)|0
  ];
}
